class SlidingWindowLimiter:
    def __init__(self, limit: int, window_seconds: int):
        if not isinstance(limit, int) or not isinstance(window_seconds, int):
            raise TypeError("limit and window_seconds must be integers")
        if limit <= 0 or window_seconds <= 0:
            raise ValueError("limit and window_seconds must both be positive integers")
        self._limit = limit
        self._window_seconds = window_seconds
        self._store: dict[str, deque[int]] = defaultdict(deque)

    def _evict(self, key: str, timestamp: int) -> None:
        dq = self._store[key]
        cutoff = timestamp - self._window_seconds
        while dq and dq[0] <= cutoff:
            dq.popleft()

    def _validate_key(self, key: str) -> None:
        if not isinstance(key, str):
            raise TypeError(f"key must be a str, got {type(key).__name__}")

    def _validate_timestamp(self, timestamp: int) -> None:
        if not isinstance(timestamp, int):
            raise TypeError(f"timestamp must be an int, got {type(timestamp).__name__}")

    def allow(self, key: str, timestamp: int) -> bool:
        self._validate_key(key)
        self._validate_timestamp(timestamp)
        self._evict(key, timestamp)
